public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option() {}

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {
        public PicklistServiceException() {}

        public PicklistServiceException(String message) {
            super(message);
        }
    }

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        try {
            if (isBlank(objectApiName)) {
                throw new PicklistServiceException('objectApiName cannot be null or blank.');
            }
            if (isBlank(fieldApiName)) {
                throw new PicklistServiceException('fieldApiName cannot be null or blank.');
            }

            String objectName = objectApiName.trim();
            String fieldName = fieldApiName.trim();

            Schema.SObjectType objectType = resolveObjectType(objectName);
            if (objectType == null) {
                throw new PicklistServiceException('Object not found: ' + objectName);
            }

            Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();
            if (objectDescribe == null) {
                throw new PicklistServiceException('Object not found: ' + objectName);
            }

            Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();
            if (fieldMap == null) {
                throw new PicklistServiceException(
                    'Field not found on object ' + objectName + ': ' + fieldName
                );
            }

            Schema.SObjectField field = resolveField(fieldMap, fieldName);
            if (field == null) {
                throw new PicklistServiceException(
                    'Field not found on object ' + objectName + ': ' + fieldName
                );
            }

            Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
            if (fieldDescribe == null) {
                throw new PicklistServiceException(
                    'Field not found on object ' + objectName + ': ' + fieldName
                );
            }

            Schema.DisplayType fieldType = fieldDescribe.getType();
            if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
                throw new PicklistServiceException(
                    'Field ' + fieldName + ' on object ' + objectName + ' is not a picklist or multi-select picklist.'
                );
            }

            List<PicklistService.Option> options = new List<PicklistService.Option>();
            List<Schema.PicklistEntry> entries = fieldDescribe.getPicklistValues();

            if (entries != null) {
                for (Schema.PicklistEntry entry : entries) {
                    if (entry == null) {
                        continue;
                    }

                    Boolean isActive = entry.isActive();
                    if (isActive == null || !isActive) {
                        continue;
                    }

                    Boolean isDefault = entry.isDefault();
                    options.add(
                        new PicklistService.Option(
                            entry.getValue(),
                            entry.getLabel(),
                            isDefault != null && isDefault
                        )
                    );
                }
            }

            return options;
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Unexpected error while retrieving picklist values: ' + e.getMessage()
            );
        }
    }

    private static Boolean isBlank(String value) {
        return value == null || value.trim().length() == 0;
    }

    private static Schema.SObjectType resolveObjectType(String objectApiName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        if (globalDescribe == null) {
            return null;
        }

        Schema.SObjectType objectType = globalDescribe.get(objectApiName);
        if (objectType == null) {
            objectType = globalDescribe.get(objectApiName.toLowerCase());
        }
        if (objectType == null) {
            objectType = globalDescribe.get(objectApiName.toUpperCase());
        }

        if (objectType != null) {
            return objectType;
        }

        for (String key : globalDescribe.keySet()) {
            if (key != null && key.equalsIgnoreCase(objectApiName)) {
                Schema.SObjectType value = globalDescribe.get(key);
                if (value != null) {
                    return value;
                }
            }
        }

        return null;
    }

    private static Schema.SObjectField resolveField(Map<String, Schema.SObjectField> fieldMap, String fieldApiName) {
        Schema.SObjectField field = fieldMap.get(fieldApiName);
        if (field == null) {
            field = fieldMap.get(fieldApiName.toLowerCase());
        }
        if (field == null) {
            field = fieldMap.get(fieldApiName.toUpperCase());
        }

        if (field != null) {
            return field;
        }

        for (Schema.SObjectField candidate : fieldMap.values()) {
            if (candidate == null) {
                continue;
            }

            Schema.DescribeFieldResult candidateDescribe = candidate.getDescribe();
            if (candidateDescribe == null || candidateDescribe.getName() == null) {
                continue;
            }

            if (candidateDescribe.getName().equalsIgnoreCase(fieldApiName)) {
                return candidate;
            }
        }

        return null;
    }
}
