public with sharing class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        Set<Id> requestedAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                requestedAccountIds.add(accountId);
                result.put(accountId, 0);
            }
        }

        if (requestedAccountIds.isEmpty()) {
            return result;
        }

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) total
            FROM Opportunity
            WHERE IsWon = true
                AND CloseDate = THIS_YEAR
                AND AccountId IN :requestedAccountIds
            GROUP BY AccountId
            WITH USER_MODE
        ]) {
            Id accountId = (Id) ar.get('AccountId');
            if (result.containsKey(accountId)) {
                Decimal amount = (Decimal) ar.get('total');
                if (amount != null) {
                    result.put(accountId, amount);
                }
            }
        }

        return result;
    }
}

