public with sharing class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork uow = null;
        Integer closedCount = 0;
        Date today = Date.today();

        for (Opportunity opportunity : OpportunitiesSelector.newInstance().selectById(opportunityIds)) {
            if (opportunity == null || opportunity.Id == null) {
                continue;
            }

            if (opportunity.StageName == 'Closed Won') {
                continue;
            }

            if (uow == null) {
                uow = Application.UnitOfWork.newInstance();
            }

            opportunity.StageName = 'Closed Won';
            opportunity.CloseDate = today;
            uow.registerDirty(opportunity);

            Deal_Won__e dealWon = new Deal_Won__e();
            dealWon.Opportunity_Id__c = opportunity.Id.toString();
            dealWon.Amount__c = opportunity.Amount;
            uow.registerPublishAfterCommit(dealWon);

            closedCount++;
        }

        if (uow != null) {
            uow.commit();
        }

        return closedCount;
    }
}
