 * EventBus.publish inside the Opportunity loop. EventBus.publish returns one
 * Database.SaveResult per platform event in the same order as the input collection,
 * so the caller can still identify each event's success or failure. This is the
 * bulk-safe pattern for trigger-invoked publishing and avoids 200 separate publish
 * calls in a single transaction.
 */
public with sharing class DealEventPublisher {

    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();

        for (Integer i = 0; i < opportunities.size(); i++) {
            Opportunity opportunity = opportunities[i];

            if (opportunity == null || opportunity.Id == null) {
                throw new IllegalArgumentException(
                    'publishStageChanges requires each Opportunity to be non-null and to contain an Id.'
                );
            }

            Deal_Stage_Change__e event = new Deal_Stage_Change__e();
            event.Opportunity_Id__c = opportunity.Id.toString();
            event.Stage__c = opportunity.StageName;
            event.Amount__c = opportunity.Amount;

            events.add(event);
        }

        results.addAll(EventBus.publish(events));

        return results;
    }
}
