import { LightningElement, track } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_MS = 300;
const MIN_SEARCH_TERM_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    @track results = [];
    @track error = null;

    __timer = null;
    __generation = 0;
    __destroyed = false;
    __latestSearchTerm = '';

    connectedCallback() {
        this.__destroyed = false;
    }

    disconnectedCallback() {
        this.__destroyed = true;
        this.__cancelPendingSearch();
        this.__generation += 1;
    }

    handleSearchChange(event) {
        if (this.__destroyed) {
            return;
        }

        const searchTerm = this.__extractSearchTerm(event);
        this.__latestSearchTerm = searchTerm;

        this.__cancelPendingSearch();
        this.__generation += 1;

        const generation = this.__generation;
        this.error = null;

        if (searchTerm.length < MIN_SEARCH_TERM_LENGTH) {
            this.results = [];
            return;
        }

        this.__timer = setTimeout(() => {
            this.__timer = null;

            if (this.__destroyed || generation !== this.__generation) {
                return;
            }

            const currentSearchTerm = this.__latestSearchTerm;
            if (currentSearchTerm.length < MIN_SEARCH_TERM_LENGTH) {
                this.results = [];
                return;
            }

            this.results = [];
            this.__runSearch(currentSearchTerm, generation);
        }, DEBOUNCE_MS);
    }

    __runSearch(searchTerm, generation) {
        searchContacts({ searchTerm })
            .then((contacts) => {
                if (this.__destroyed || generation !== this.__generation) {
                    return;
                }

                this.results = contacts || [];
                this.error = null;
            })
            .catch((err) => {
                if (this.__destroyed || generation !== this.__generation) {
                    return;
                }

                this.results = [];
                this.error = {
                    body: {
                        message: this.__formatError(err)
                    }
                };
            });
    }

    __cancelPendingSearch() {
        if (this.__timer) {
            clearTimeout(this.__timer);
            this.__timer = null;
        }
    }

    __extractSearchTerm(event) {
        if (!event) {
            return '';
        }

        let value;

        if (event.target && event.target.value !== undefined && event.target.value !== null) {
            value = event.target.value;
        } else if (event.detail !== undefined && event.detail !== null) {
            if (typeof event.detail === 'string') {
                value = event.detail;
            } else if (
                event.detail.value !== undefined &&
                event.detail.value !== null
            ) {
                value = event.detail.value;
            }
        }

        if (typeof value === 'string') {
            return value.trim();
        }

        if (typeof value === 'number') {
            return String(value).trim();
        }

        return '';
    }

    __formatError(error) {
        if (typeof error === 'string') {
            return error;
        }

        if (
            error &&
            error.body &&
            typeof error.body.message === 'string' &&
            error.body.message
        ) {
            return error.body.message;
        }

        if (error && typeof error.message === 'string' && error.message) {
            return error.message;
        }

        return 'An error occurred.';
    }
}
