import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    @api recordId;

    status = 'loading';
    opportunities = [];
    errorMessage = null;

    requestCount = 0;
    destroyed = false;

    connectedCallback() {
        this.destroyed = false;
        this.loadOpenOpportunities();
    }

    disconnectedCallback() {
        this.destroyed = true;
    }

    get isLoading() {
        return this.status === 'loading';
    }

    get hasError() {
        return this.status === 'error';
    }

    get hasOpportunities() {
        return this.status === 'success' && this.opportunities.length > 0;
    }

    get isEmpty() {
        return this.status === 'success' && this.opportunities.length === 0;
    }

    handleRetry() {
        if (this.isLoading) {
            return;
        }
        this.loadOpenOpportunities();
    }

    loadOpenOpportunities() {
        const requestId = ++this.requestCount;

        this.status = 'loading';
        this.errorMessage = null;
        this.opportunities = [];

        getOpenOpportunities({ accountId: this.recordId })
            .then((data) => {
                if (this.destroyed || requestId !== this.requestCount) {
                    return;
                }

                this.opportunities = data || [];
                this.errorMessage = null;
                this.status = 'success';
            })
            .catch((error) => {
                if (this.destroyed || requestId !== this.requestCount) {
                    return;
                }

                let message = 'Unknown error';

                if (error && error.body && error.body.message) {
                    message = error.body.message;
                } else if (error && error.message) {
                    message = error.message;
                }

                this.errorMessage = message;
                this.opportunities = [];
                this.status = 'error';
            });
    }
}
