```javascript
import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    statsLoaded = false;
    waiting = 0;
    longestWaitMinutes = 0;
    error = null;

    pollTimer = null;
    inFlight = false;
    generation = 0;

    visibilityListener = () => {
        this.handleVisibilityChange();
    };

    connectedCallback() {
        this.generation += 1;
        this.inFlight = false;
        this.stopPolling();

        document.removeEventListener('visibilitychange', this.visibilityListener);
        document.addEventListener('visibilitychange', this.visibilityListener);

        if (!this.isHidden()) {
            this.loadStats();
            this.ensurePolling();
        }
    }

    disconnectedCallback() {
        this.generation += 1;
        this.stopPolling();
        document.removeEventListener('visibilitychange', this.visibilityListener);
        this.inFlight = false;
    }

    handleVisibilityChange() {
        if (this.isHidden()) {
            this.stopPolling();
        } else {
            this.loadStats();
            this.ensurePolling();
        }
    }

    loadStats() {
        if (this.inFlight || this.isHidden()) {
            return;
        }

        this.inFlight = true;
        const generation = this.generation;

        getQueueStats().then(
            (stats) => {
                if (generation !== this.generation) {
                    return;
                }

                this.inFlight = false;
                this.error = null;
                this.statsLoaded = true;
                this.waiting = stats && stats.waiting != null ? stats.waiting : 0;
                this.longestWaitMinutes =
                    stats && stats.longestWaitMinutes != null ? stats.longestWaitMinutes : 0;

                this.ensurePolling();
            },
            (err) => {
                if (generation !== this.generation) {
                    return;
                }

                this.inFlight = false;
                this.error =
                    (err && err.body && err.body.message) ||
                    (err && err.message) ||
                    'Unable to load queue statistics.';

                this.ensurePolling();
            }
        );
    }

    ensurePolling() {
        if (this.isHidden() || this.pollTimer !== null) {
            return;
        }

        const generation = this.generation;

        this.pollTimer = setInterval(() => {
            if (generation !== this.generation) {
                return;
            }

            if (this.isHidden()) {
                this.stopPolling();
                return;
            }

            this.loadStats();
        }, 60000);
    }

    stopPolling() {
        if (this.pollTimer !== null) {
            clearInterval(this.pollTimer);
            this.pollTimer = null;
        }
    }

    isHidden() {
        return document.visibilityState === 'hidden';
    }
}
