import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/showToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const FREE_EMAIL_DOMAINS = new Set([
    'gmail.com',
    'yahoo.com',
    'hotmail.com',
    'outlook.com'
]);

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleInput(event) {
        const field = event.target.dataset.field;
        if (field) {
            this[field] = event.detail.value;
        }
    }

    handleRegister() {
        const emailInput = this.template.querySelector(
            'lightning-input[data-field="email"]'
        );

        if (emailInput) {
            const email = String(this.email || '').trim();
            const domain = email.includes('@')
                ? email.split('@').pop().toLowerCase()
                : '';

            if (FREE_EMAIL_DOMAINS.has(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        let allValid = true;
        this.template.querySelectorAll('lightning-input').forEach((input) => {
            const valid = input.reportValidity();
            if (!valid) {
                allValid = false;
            }
        });

        if (!allValid) {
            return;
        }

        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'success',
                        title: 'Registered'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'error',
                        title: 'Registration failed',
                        message: error?.body?.message
                    })
                );
            });
    }
}
