public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static final Set<Id> loggedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (triggerNew == null || triggerOld == null || triggerNew.isEmpty()) {
            return;
        }

        Map<Id, Decimal> oldAmountByOpportunityId = new Map<Id, Decimal>();
        for (SObject record : triggerOld) {
            Opportunity oldOpp = (Opportunity) record;
            oldAmountByOpportunityId.put(oldOpp.Id, oldOpp.Amount);
        }

        List<Task> tasksToInsert = new List<Task>();

        for (SObject record : triggerNew) {
            Opportunity opp = (Opportunity) record;

            if (opp.Id == null || loggedOpportunityIds.contains(opp.Id)) {
                continue;
            }

            Decimal oldAmount = oldAmountByOpportunityId.get(opp.Id);
            if (opp.Amount != oldAmount) {
                loggedOpportunityIds.add(opp.Id);

                tasksToInsert.add(
                    new Task(
                        Subject = 'Amount changed',
                        WhatId = opp.Id,
                        Status = 'Completed'
                    )
                );
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }

    @TestVisible
    private static void clearLoggedOpportunityIdsForTest() {
        loggedOpportunityIds.clear();
    }
}
```

